void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord-2.*iResolution.xy)*2./iResolution.y;


 	uv = fract(uv);

    //uv.x = smoothstep(.8, 1., fract(length(uv)*5.));


    // Time varying pixel color

    vec2 slope = vec2(uv.x + uv.y, uv.x + (.3*sin(iTime*2.)+.5)*uv.y)*.5;
    slope = smoothstep(.49, .5, slope)*(.3*sin(iTime*2.)+.5);

    vec3 col = vec3(slope, slope.x);

    // Output to screen
    fragColor = vec4(col,1.0);
}
